/**
 * SQL safety layer for analytics queries.
 *
 * All queries generated by the LLM are validated here before execution:
 * - Only SELECT / WITH ... SELECT allowed
 * - DML / DDL keywords blocked
 * - Table whitelist enforced on EVERY relation reference (FROM/JOIN and comma lists)
 * - Function calls restricted to an allow-list; schema-qualified calls rejected
 * - An outer LIMIT 500 is always applied at execution
 *
 * Esta camada NÃO é a fronteira de segurança. Quem segura é o banco: a RPC roda como
 * `analytics_reader` (SELECT só nestas tabelas, sem EXECUTE em função de aplicação, em
 * transação somente leitura — migration 20260921160000). A validação aqui existe para
 * devolver ao modelo um erro legível, antes do `permission denied`.
 */

const MAX_QUERY_LENGTH = 4000
const MAX_LIMIT = 500

const ALLOWED_TABLES = new Set([
	"arranchamento",
	"meal_presences",
	"units",
	"mess_halls",
	"kitchen",
	"daily_menu",
	"menu_items",
	"recipes",
	"quantity_estimate",
	"quantity_estimate_item",
	"arp_item",
	"empenho",
	"empenho_item",
	"ingredient",
	"production_task",
	"meal_type",
	"recipe_ingredients",
	"v_meal_presences_with_user",
	"v_user_identity",
])

/** Schemas em que as tabelas liberadas moram — o `search_path` da RPC. */
const ALLOWED_SCHEMAS = new Set(["core", "kitchen", "procurement", "finance"])

/** Funções que o assistente usa para agregar e formatar. Chamada fora daqui é recusada. */
const ALLOWED_FUNCTIONS = new Set([
	"count",
	"sum",
	"avg",
	"min",
	"max",
	"coalesce",
	"nullif",
	"greatest",
	"least",
	"round",
	"floor",
	"ceil",
	"ceiling",
	"abs",
	"trunc",
	"date_trunc",
	"date_part",
	"extract",
	"to_char",
	"to_date",
	"make_date",
	"age",
	"lower",
	"upper",
	"trim",
	"length",
	"concat",
	"substring",
	"left",
	"right",
	"replace",
	"split_part",
	"initcap",
	"string_agg",
	"array_agg",
	"row_number",
	"rank",
	"dense_rank",
	"ntile",
	"lag",
	"lead",
	"first_value",
	"last_value",
	"percentile_cont",
	"percentile_disc",
	"stddev",
	"variance",
	"bool_and",
	"bool_or",
	"generate_series",
	"cast",
	"now",
	"date",
	"position",
])

/** Palavras-chave que legitimamente vêm antes de "(" sem serem chamada de função. */
const KEYWORDS_BEFORE_PAREN = new Set([
	"select",
	"from",
	"join",
	"where",
	"in",
	"exists",
	"any",
	"all",
	"some",
	"as",
	"over",
	"filter",
	"group",
	"values",
	"and",
	"or",
	"not",
	"on",
	"using",
	"when",
	"then",
	"else",
	"distinct",
	"union",
	"intersect",
	"except",
	"row",
	"array",
	"limit",
	"offset",
	"having",
	"by",
	"between",
	"like",
	"ilike",
	"is",
	"case",
	"end",
	"with",
])

/**
 * Palavras que encerram a lista de relações de um FROM (no mesmo nível de parênteses).
 * `ON`/`USING`/`JOIN` NÃO encerram: `FROM a JOIN b ON a.x = b.x, core.user_data d` continua
 * sendo lista de relações depois da condição — vírgula no nível do FROM só pode abrir outra
 * relação (dentro de expressão ela fica num nível de parênteses mais fundo).
 */
const FROM_LIST_TERMINATORS = new Set(["where", "group", "order", "limit", "having", "union", "intersect", "except", "offset", "fetch"])

const BLOCKED_KEYWORDS = [
	"INSERT",
	"UPDATE",
	"DELETE",
	"DROP",
	"TRUNCATE",
	"ALTER",
	"COPY",
	"$$",
	"EXECUTE",
	"CALL",
	"GRANT",
	"REVOKE",
	"INTO",
	"LATERAL",
	"MERGE",
	"LOCK",
	"SET",
	// `TABLE x` é relação sem FROM; `WINDOW nome AS (...)` se confundia com nome de CTE.
	"TABLE",
	"WINDOW",
]

type Token = { kind: "ident" | "string" | "number" | "punct"; value: string }

/**
 * Sintaxe é só token de pontuação. O token de string guarda o conteúdo sem aspas e o identificador
 * entre aspas guarda o nome: ler pelo valor fazia `'('` e `"("` abrirem nível de parênteses.
 */
function isPunct(token: Token | undefined, value: string): boolean {
	return token?.kind === "punct" && token.value === value
}

/**
 * Tokenizador mínimo. Recusa (retorna string de erro) o que abriria ambiguidade entre o que
 * o validador lê e o que o Postgres executa: comentário, dollar-quoting, string com escape
 * (E'…', U&'…') e identificador entre aspas com caractere fora de [A-Za-z0-9_].
 */
function tokenize(sql: string): Token[] | string {
	const tokens: Token[] = []
	let i = 0
	while (i < sql.length) {
		const ch = sql[i]
		if (/\s/.test(ch)) {
			i++
			continue
		}
		if (sql.startsWith("--", i) || sql.startsWith("/*", i)) return "Comentários não são permitidos"
		if (ch === "$" || ch === "\\" || ch === "`") return `Caractere não permitido: ${ch}`
		if (ch === "'") {
			const prev = tokens.at(-1)
			if (prev?.kind === "ident" && /^(e|u&|b|x|n)$/i.test(prev.value)) return "Strings com prefixo não são permitidas"
			let j = i + 1
			let value = ""
			while (j < sql.length) {
				if (sql[j] === "'") {
					if (sql[j + 1] === "'") {
						value += "'"
						j += 2
						continue
					}
					break
				}
				value += sql[j]
				j++
			}
			if (j >= sql.length) return "String não terminada"
			tokens.push({ kind: "string", value })
			i = j + 1
			continue
		}
		if (ch === '"') {
			const close = sql.indexOf('"', i + 1)
			if (close === -1) return "Identificador não terminado"
			const value = sql.slice(i + 1, close)
			// Qualquer conteúdo sem aspas vale: o identificador não sai do token (`""` escapado
			// fecharia e reabriria, e aí vira dois tokens que a varredura confere). Rótulo de
			// gráfico em português — `AS "Total de refeições"` — é o uso comum.
			if (value.length === 0) return "Identificador entre aspas vazio"
			tokens.push({ kind: "ident", value: value.toLowerCase() })
			i = close + 1
			continue
		}
		const ident = /^[A-Za-z_][A-Za-z0-9_]*/.exec(sql.slice(i))
		if (ident) {
			tokens.push({ kind: "ident", value: ident[0].toLowerCase() })
			i += ident[0].length
			continue
		}
		const num = /^[0-9]+(\.[0-9]+)?/.exec(sql.slice(i))
		if (num) {
			tokens.push({ kind: "number", value: num[0] })
			i += num[0].length
			continue
		}
		if (sql.startsWith("::", i)) {
			tokens.push({ kind: "punct", value: "::" })
			i += 2
			continue
		}
		tokens.push({ kind: "punct", value: ch })
		i++
	}
	return tokens
}

/** Nome de CTE declarado em `WITH nome AS (` ou `, nome AS (`. */
function collectCteNames(tokens: Token[]): Set<string> {
	const names = new Set<string>()
	for (let i = 0; i + 2 < tokens.length; i++) {
		const [a, b, c] = [tokens[i], tokens[i + 1], tokens[i + 2]]
		if (a.kind === "ident" && b.kind === "ident" && b.value === "as" && isPunct(c, "(")) {
			const prev = tokens[i - 1]
			if (prev && (prev.value === "with" || prev.value === ",")) names.add(a.value)
		}
	}
	return names
}

/** Lê uma referência de relação a partir de `i`; devolve o erro, se houver. */
function checkRelationAt(tokens: Token[], i: number, cteNames: Set<string>): string | null {
	const first = tokens[i]
	if (!first) return "Relação ausente"
	if (isPunct(first, "(")) {
		// `FROM (SELECT …)` é subquery, validada pelo resto da varredura. Mas `FROM (a JOIN b …)`
		// é JOIN entre parênteses: a PRIMEIRA relação de dentro não vem depois de FROM/JOIN
		// nenhum, e passava sem conferência (`FROM (auth.users u CROSS JOIN units x)`).
		let j = i
		while (isPunct(tokens[j], "(")) j++
		const inner = tokens[j]?.value
		if (inner === "select" || inner === "with" || inner === "values") return null
		return checkRelationAt(tokens, j, cteNames)
	}
	if (first.kind !== "ident") return `Relação inválida: ${first.value}`
	let schema: string | null = null
	let table = first.value
	if (tokens[i + 1]?.value === "." && tokens[i + 2]?.kind === "ident") {
		schema = first.value
		table = tokens[i + 2].value
	}
	if (tokens[schema ? i + 3 : i + 1]?.value === "(") return `Função como relação não permitida: ${table}`
	if (schema && !ALLOWED_SCHEMAS.has(schema)) return `Tabela não permitida: ${table}`
	if (!schema && cteNames.has(table)) return null
	if (!ALLOWED_TABLES.has(table)) return `Tabela não permitida: ${table}`
	return null
}

/** Funções em que `FROM` é parte da sintaxe, não relação. */
const FUNCTIONS_WITH_FROM_ARGUMENT = new Set(["extract", "substring", "trim"])

/** Etapa 1: checagens no texto (antes de tokenizar). Devolve o erro, se houver. */
function checkRawText(normalized: string, up: string): string | null {
	if (normalized.length > MAX_QUERY_LENGTH) return "SQL muito longa"

	// Only SELECT or WITH … SELECT (CTEs)
	if (!up.startsWith("SELECT") && !up.startsWith("WITH")) return "Apenas SELECT permitido"

	if (normalized.includes(";")) return "Múltiplas instruções não são permitidas"

	return findBlockedKeyword(normalized, up)
}

/** Block DML / DDL — no texto cru, de propósito conservador (inclusive dentro de string). */
function findBlockedKeyword(normalized: string, up: string): string | null {
	for (const kw of BLOCKED_KEYWORDS) {
		if (kw === "$$" ? up.includes(kw) : new RegExp(`\\b${kw}\\b`, "i").test(normalized)) return `Keyword proibida: ${kw}`
	}
	return null
}

/** Estado da varredura de tokens. */
type TokenScan = {
	tokens: Token[]
	cteNames: Set<string>
	/** Contexto por nível de parênteses: dentro da lista de relações de um FROM? */
	inFromList: boolean[]
	depth: number
}

/** Etapa 2: tokeniza e varre os tokens. Devolve o erro, se houver. */
function checkTokens(normalized: string): string | null {
	const tokens = tokenize(normalized)
	if (typeof tokens === "string") return tokens
	return scanTokens({ tokens, cteNames: collectCteNames(tokens), inFromList: [false], depth: 0 })
}

function scanTokens(scan: TokenScan): string | null {
	for (let i = 0; i < scan.tokens.length; i++) {
		const token = scan.tokens[i]
		// Parêntese só de pontuação: o literal `'('` (ou `')'`) não muda o nível. Contado pelo
		// valor, `ON m.x = '(', auth.users a` descia um nível e a vírgula da lista de relações
		// deixava de ser conferida.
		if (isPunct(token, "(")) {
			scan.depth++
			scan.inFromList[scan.depth] = false
			continue
		}
		if (isPunct(token, ")")) {
			scan.inFromList[scan.depth] = false
			scan.depth = Math.max(0, scan.depth - 1)
			continue
		}
		const err = token.kind === "ident" ? checkIdentToken(scan, i) : checkFromListComma(scan, i)
		if (err) return err
	}
	return null
}

function checkIdentToken(scan: TokenScan, i: number): string | null {
	const token = scan.tokens[i]
	// Catálogo e funções de sistema: nada de pg_* nem information_schema.
	if (token.value.startsWith("pg_") || token.value === "information_schema") {
		return `Identificador não permitido: ${token.value}`
	}

	if (token.value === "from" || token.value === "join") return checkRelationKeyword(scan, i)

	if (FROM_LIST_TERMINATORS.has(token.value)) scan.inFromList[scan.depth] = false

	return checkFunctionCall(scan.tokens, i)
}

/** `FROM`/`JOIN`: confere a relação seguinte e abre a lista de relações do nível. */
function checkRelationKeyword(scan: TokenScan, i: number): string | null {
	const token = scan.tokens[i]
	// `EXTRACT(x FROM y)` e `SUBSTRING(a FROM b)` usam FROM sem ser relação.
	const opener = findOpenerFunction(scan.tokens, i)
	if (token.value === "from" && opener && FUNCTIONS_WITH_FROM_ARGUMENT.has(opener)) return null
	const err = checkRelationAt(scan.tokens, i + 1, scan.cteNames)
	if (err) return err
	scan.inFromList[scan.depth] = true
	return null
}

/** Identificador seguido de "(": só função liberada, palavra-chave ou tipo. */
function checkFunctionCall(tokens: Token[], i: number): string | null {
	if (tokens[i + 1]?.value !== "(") return null
	const token = tokens[i]
	const prev = tokens[i - 1]
	if (prev?.value === ".") return `Função qualificada não permitida: ${token.value}`
	// Tipo depois de `::` ou `AS` de verdade: o literal `'::'` antes de `f(` não isenta a função.
	const isType = isPunct(prev, "::") || (prev?.kind === "ident" && prev.value === "as")
	if (!isType && !ALLOWED_FUNCTIONS.has(token.value) && !KEYWORDS_BEFORE_PAREN.has(token.value)) {
		return `Função não permitida: ${token.value}`
	}
	return null
}

/** Vírgula no nível de uma lista de relações abre outra relação. */
function checkFromListComma(scan: TokenScan, i: number): string | null {
	if (scan.tokens[i].value !== "," || !scan.inFromList[scan.depth]) return null
	return checkRelationAt(scan.tokens, i + 1, scan.cteNames)
}

/** Etapa 3: todo `LIMIT n` do texto (inclusive dentro de string) até o máximo. */
function checkLimits(normalized: string): string | null {
	const limitMatches = [...normalized.matchAll(/\bLIMIT\s+(\d+)\b/gi)]
	for (const [, rawLimit] of limitMatches) {
		if (Number(rawLimit) > MAX_LIMIT) return `LIMIT máximo permitido: ${MAX_LIMIT}`
	}
	return null
}

export function validateSql(sql: string): { valid: boolean; error?: string } {
	if (!sql?.trim()) return { valid: false, error: "SQL vazio" }

	const normalized = sql.trim().replace(/;$/, "")
	const error = checkRawText(normalized, normalized.toUpperCase()) ?? checkTokens(normalized) ?? checkLimits(normalized)
	return error === null ? { valid: true } : { valid: false, error }
}

/**
 * Nome da função cujo "(" envolve a posição `i` no mesmo nível, se houver. Só parêntese de
 * pontuação: pelo valor, `trim('(') FROM auth.users` casava o `)` com o literal e o FROM da
 * relação passava por argumento do `trim`.
 */
function findOpenerFunction(tokens: Token[], i: number): string | null {
	let depth = 0
	for (let j = i - 1; j >= 0; j--) {
		const token = tokens[j]
		if (isPunct(token, ")")) depth++
		else if (isPunct(token, "(")) {
			if (depth === 0) return tokens[j - 1]?.kind === "ident" ? tokens[j - 1].value : null
			depth--
		}
	}
	return null
}

export async function executeSql(sql: string): Promise<Record<string, unknown>[]> {
	const { getSupabaseServerClient } = await import("@/lib/supabase.server")

	// LIMIT externo SEMPRE: `LIMIT ALL` ou `FETCH FIRST n` dentro da query não furam o teto,
	// porque a RPC agrega o resultado inteiro num jsonb só.
	const trimmedSql = sql.trim().replace(/;$/, "")
	const safeSql = `SELECT * FROM (${trimmedSql}) AS analytics_q LIMIT ${MAX_LIMIT}`

	const { data, error } = await getSupabaseServerClient().rpc("execute_analytics_query", {
		query: safeSql,
	})
	// O erro do SQL gerado volta para o modelo corrigir a consulta; não é texto de tela.
	// nosemgrep: sisub-raw-db-error-message
	if (error) throw new Error(error.message)

	return Array.isArray(data) ? (data as Record<string, unknown>[]) : []
}
